/**
 * One colour per kind of named object. This file is the only place to edit them: it feeds the
 * editor (TextMate scopes + token colours) and the pages (`--kind-<kind>` CSS variables).
 *
 * The TextMate file is generated by `langium generate` and gitignored, so the per-kind rules
 * are added to it at load time (`withKindScopes`) instead of being edited in.
 */

/** Declared and referenced as a quoted name: `location "Tavern"`. */
export const QUOTED_KINDS = ['location', 'npc', 'faction', 'party', 'quest', 'objective', 'event'] as const;
/** Declared as an identifier: `function reward`, `state Mood { ... }`. */
export const IDENTIFIER_KINDS = ['function', 'state'] as const;

export type Kind = (typeof QUOTED_KINDS)[number] | (typeof IDENTIFIER_KINDS)[number];

export const KIND_COLORS: Record<Kind, string> = {
  location: '#4ec9b0',
  npc: '#e2b04a',
  faction: '#a78bfa',
  party: '#f0883e',
  quest: '#89d185',
  objective: '#a8d96b',
  event: '#f47067',
  function: '#7aa2c7',
  state: '#7aa2c7',
};

const kindScope = (kind: Kind) => `entity.name.${kind}.dnd-dsl`;

const QUOTED_NAME_PLAIN = String.raw`(?:"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')`;
const QUOTED_NAME = `(${QUOTED_NAME_PLAIN})`;
/** What a `->` step after this kind names. */
const STEP_KIND = { location: 'location', quest: 'objective' } as const;
// `quest completed "A"`, `objective failed "O"`, `quest accepted "A"`, `event triggered "E"`
const STATUS_WORD = String.raw`(\s+(?:completed|failed|accepted|triggered))?`;

type TmPattern = { include?: string; [key: string]: unknown };
type TmGrammar = { patterns: TmPattern[]; [key: string]: unknown };

/** The grammar with a rule per kind, placed before the generic keyword and string rules so it wins at the same position. */
export function withKindScopes(grammar: TmGrammar): TmGrammar {
  const keyword = { name: 'keyword.control.dnd-dsl' };
  const quoted = QUOTED_KINDS.map((kind): TmPattern => {
    const stepKind = STEP_KIND[kind as keyof typeof STEP_KIND];
    const head = String.raw`\b(${kind})\b${STATUS_WORD}\s+${QUOTED_NAME}`;
    if (!stepKind) return { match: head, captures: { 1: keyword, 2: keyword, 3: { name: kindScope(kind) } } };
    // `location "A" -> "B"`, `quest "Q" -> "O"`, `quest "Q" . objectives "O"`: the names after a step are the child kind.
    return {
      match: String.raw`${head}((?:\s*(?:->|\.\s*(?:sublocations|objectives))\s*${QUOTED_NAME_PLAIN})*)`,
      captures: {
        1: keyword, 2: keyword, 3: { name: kindScope(kind) },
        4: { patterns: [
          { name: 'keyword.control.dnd-dsl', match: String.raw`\b(?:sublocations|objectives)\b` },
          { name: kindScope(stepKind), match: QUOTED_NAME_PLAIN },
        ] },
      },
    };
  });
  const identifiers = IDENTIFIER_KINDS.map((kind): TmPattern => ({
    match: String.raw`\b(${kind})\s+([A-Za-z_]\w*)`,
    captures: { 1: keyword, 2: { name: kindScope(kind) } },
  }));

  // `trigger "The Beginning"` names an event without the `event` keyword.
  const trigger: TmPattern = {
    match: String.raw`\b(trigger)\s+${QUOTED_NAME}`,
    captures: { 1: keyword, 2: { name: kindScope('event') } },
  };

  // `entry "X"` and the target of `exit "Door" to "Hall"` name a location. The exit's own label stays a string.
  const entry: TmPattern = {
    match: String.raw`\b(entry)\s+${QUOTED_NAME}`,
    captures: { 1: keyword, 2: { name: kindScope('location') } },
  };
  const exit: TmPattern = {
    match: String.raw`\b(exit)\s+${QUOTED_NAME}\s+(to)\s+${QUOTED_NAME}`,
    captures: { 1: keyword, 2: { name: 'string.quoted.dnd-dsl' }, 3: keyword, 4: { name: kindScope('location') } },
  };

  const patterns = [...grammar.patterns];
  const firstRule = patterns.findIndex(p => !p.include);
  patterns.splice(firstRule < 0 ? patterns.length : firstRule, 0, ...quoted, trigger, entry, exit, ...identifiers);
  return { ...grammar, patterns };
}

/** For `editor.tokenColorCustomizations.textMateRules`. */
export function kindTokenRules() {
  return (Object.keys(KIND_COLORS) as Kind[]).map(kind => ({
    scope: kindScope(kind),
    settings: { foreground: KIND_COLORS[kind] },
  }));
}

/** Sets `--kind-<kind>` on the page so CSS and inline styles use the same palette as the editor. */
export function applyKindColorVars(root: HTMLElement = document.documentElement) {
  for (const kind of Object.keys(KIND_COLORS) as Kind[]) {
    root.style.setProperty(`--kind-${kind}`, KIND_COLORS[kind]);
  }
}
